import{_ as o,l as n,o as e,c as i,v as t,p as l,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"B+ 树作为结构","description":"","frontmatter":{"title":"B+ 树作为结构","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bplus-as-ds.md","filePath":"cs/bplus-as-ds.md","lastUpdated":1789023840000}'),h={name:"cs/bplus-as-ds.md"};function B(_,a,m,u,E,A){const s=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="b-树作为结构" tabindex="-1">B+ 树作为结构 <a class="header-anchor" href="#b-树作为结构" aria-label="Permalink to &quot;B+ 树作为结构&quot;">​</a></h1><div class="epigraph"><p>内节点只存分隔键与孩子指针，真正的记录全在叶上；叶再串成有序链表，范围扫描不必回到根。</p><footer>—— 据 Bayer and McCreight, Organization and Maintenance of Large Ordered Indexes, 1972；Comer, The Ubiquitous B-Tree, CSUR 1979 整理</footer></div><p><a href="/cs/btree-external">上一课</a>钉了高扇出、叶同深、满则分裂，并声明卫星可在内节点、B+ 细节后置。数据库栏的<a href="/cs/bplus-index">B+ 树索引</a>会谈 rid 与缓冲池。本课不重写库存储，也不从 Bayer 的总问题另起。缺口是把 B+ 当作内存/外存都可用的<strong>有序字典表示</strong>：数据只在叶、内节点当路标、叶链支持后继迭代。堆课马上要用「不必全序遍历」的对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>B 树内节点带记录，范围扫描要中序走内节点，页内布局与叶不同。B+ 约定：查找总是降到叶；内节点的键只是分隔，可以是叶中键的副本。缺口不是再证 \\(\\Theta(\\log_t n)\\) 高度，而是<strong>后继 = 叶上右邻，或叶链下一页</strong>，从而顺序遍历对 I/O 与 cache 都是连续的。</p><p>分裂：叶满则对半，中位键<strong>拷贝</strong>上推（叶仍留该键）；内节点满则中位<strong>上移</strong>。这与 B 树「记录跟着键走」不同。</p><p><span class="marginnote">本课对象是结构。聚簇、二级索引、覆盖扫描是数据库课用同一结构干的事，不在这里重讲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：内节点二分选孩子直到叶，叶内再找。插入只在叶分裂；分隔键上传可能级联。范围 \\([L,R]\\)：找到 \\(L\\) 所在叶，沿 <code>next</code> 走到超过 \\(R\\)。</p>',9)),(e(),l(c,null,{default:r(()=>[p(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%86%85%E8%8A%82%E7%82%B9%EF%BC%9A%E5%88%86%E9%9A%94%E9%94%AE%22%5D%20--%3E%20LEAF%5B%22%E5%8F%B6%EF%BC%9A%E5%85%A8%E9%83%A8%E8%AE%B0%E5%BD%95%22%5D%0A%20%20LEAF%20--%3E%20NXT%5B%22%E5%8F%B6%E9%93%BE%EF%BC%9A%E5%90%8E%E7%BB%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>内存里 B+ 仍改善扫描局部性：叶可以是大块数组。扇出由页或 cache 行宽决定，与上一课相同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>点查 I/O 次数仍是高度；范围的额外 I/O 与输出页数成正比，而不是与树的内部路径成正比。这是相对 BST「后继可能上爬」的优势，也是相对散列「无序」的优势。</p><p>内节点键可压缩（前缀），只影响扇出，不影响「数据在叶」。删除合并与 B 树对称；实践可惰性标删，结构课只要求不变式可恢复。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入哈希索引、WAL、蟹行锁。也不把 B+ 写成必须外存：内存有序字典同样能用。优先队列不需要中序与范围，下一课用堆，避免为 extract-min 维护整棵多路树。</p><p>后课默认：要有序、要范围、要高扇出，用 B 树族；B+ 是扫描友好的变体。只要反复取最小，用堆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>B+：记录只在叶，内节点是路标，叶链走范围。</li><li>分裂时叶键拷贝上推，与 B 树记录上移不同。</li><li>优先队列合同更窄，下一课堆。</li><li>出处：Bayer and McCreight, 1972；Comer, <em>CSUR</em>, 1979；对照 CLRS B 树章。</li></ul>',9))])}const T=o(h,[["render",B]]);export{f as __pageData,T as default};
